   try{camera.targetTexture=render;camera.Render();RenderTexture.active=render;pixels=new Texture2D(1200,800,TextureFormat.RGB24,false);pixels.ReadPixels(new Rect(0,0,1200,800),0,0);pixels.Apply();File.WriteAllBytes(path,pixels.EncodeToPNG());images.Add(new Image{path=path,label=label,eye=camera.transform.position,forward=camera.transform.forward,up=camera.transform.up,fov=camera.fieldOfView,aspect=camera.aspect});}
   finally{camera.targetTexture=target;RenderTexture.active=active;if(pixels!=null)UnityEngine.Object.Destroy(pixels);RenderTexture.ReleaseTemporary(render);}
   var seen=new HashSet<Shader>();foreach(var renderer in UnityEngine.Object.FindObjectsByType<Renderer>(FindObjectsInactive.Exclude))if(renderer.enabled&&renderer.gameObject.activeInHierarchy)foreach(var material in renderer.sharedMaterials)if(material!=null&&seen.Add(material.shader))foreach(var message in ShaderUtil.GetShaderMessages(material.shader))if(message.severity.ToString()=="Error")shaderErrors.Add(material.shader.name+": "+message.message);
   Need(shaderErrors.Count==0,"Actual rendered material shader errors: "+String.Join(" | ",shaderErrors.ToArray()));
  }
