    Need(loop.Ready&&loop.Map.MapId=="range"&&other.Lobby.SelectedMap!=null&&!rootPeer.Lobby.SelectedMap.Active&&ReadyMembers(rootPeer.Lobby)==1&&loop.Lobby.Visible,"Host waits for actual independent client loader before entry");result.hostWaitedForActualClientLoad=true;loop.StartPlaying();Need(loop.Lobby.Visible&&loop.LanSession.MapEntryBlocked,"Direct early Root entry cannot bypass real load barrier");result.earlyEntryBlocked=true;
    privateMap=new GameObject("Isolated actual client map loader").AddComponent<Ashfall.Integration.Playable.World.R23PlayableMap>();privateMap.transform.position=Vector3.right*10000;privateMap.Load("range");end=Time.realtimeSinceStartup+40;while(privateMap.IsLoading&&Time.realtimeSinceStartup<end){pump.Tick(null);yield return null;}Need(privateMap.IsLoaded&&privateMap.ManifestSha256==other.Lobby.SelectedMap.ManifestHash,"Independent actual Range payload loaded and identity matches");Need(privateMap.GetComponentsInChildren<Collider>(true).Length>0,"Independent loader owns actual cooked collision");result.independentLoadedMaps++;Need(other.Lobby.ReportMapLoaded(privateMap.ManifestSha256),"Client acknowledges real loaded bytes");
