  [Serializable]sealed class RoundResult{public bool success,nativeExecuted,hostUiStart,threeSecondBarrier,hostActualRound,clientActualRound,clientControlsLocked,assignedTeamApplied,sharedZoneSeedApplied,cleanup,headsetVerified=false,sharedCombatVerified=false;public float hostClockResidual,clientClockResidual;public double hostClientOffset=1000,clientHostOffset=2000;public int ruleValuesCompared;public List<string> cases=new List<string>();}
  static void PumpRound(R23PlayableLoop loop,GuestPump pump){pump.Tick(null);if(loop.LanRoundBound&&loop.MatchActive)loop.TickMatch(Mathf.Max(0,Time.unscaledDeltaTime),true);}
  static int ActualTeam(R24LanLobby lobby){foreach(var member in lobby.Members)if(member.Actor==lobby.OwnActor)return member.Team;throw new InvalidOperationException("Actual admitted self team");}
  static void CheckRoundRoot(R23PlayableLoop loop,R24LanLobby room,Ashfall.Integration.Playable.Match.R24PlayableMatchRules expected,RoundResult result)
  {
   Need(loop.Ready&&loop.LanRoundBound&&loop.MatchActive&&loop.ActualMatchRules!=null&&loop.Map.MapId==expected.MapId&&!loop.Lobby.Visible,"Actual Root running shared rules/clock");
   foreach(string key in Ashfall.Integration.Playable.Match.R24PlayableMatchRules.SourceKeys){Need(System.Object.Equals(loop.ActualMatchRules.ReadSourceValue(key),expected.ReadSourceValue(key)),"Actual Root source rule: "+key);result.ruleValuesCompared++;}
   Need(loop.Gameplay.LocalMatchHealth!=null&&loop.Gameplay.LocalMatchHealth.Team==ActualTeam(room)&&loop.LocalMatchTeam==ActualTeam(room),"Actual assigned Session team reaches real local Health owner");Need(Mathf.Abs(loop.Gameplay.Health-expected.StartingHealth)<.001f&&Mathf.Abs(loop.Gameplay.Shield-expected.StartingShield)<.001f,"Actual starting Health/shield from shared snapshot");Need(Vector3.Distance((Vector3)Read(loop.Rig,"spawn"),loop.Map.GameSpawn)<.001f,"Existing Root chooses actual game spawn");
   Ashfall.Integration.Playable.TeamLaunch.R24LaunchMapInfo map;Need(loop.LaunchMapCatalog.TryRead(expected.MapId,out map),"Actual source zone bounds available");var random=new R24LanRoundRandom(room.SelectedMap.Seed);var zone=new Ashfall.Integration.Playable.MatchZone.R24MatchZoneHost(new Ashfall.Integration.Playable.MatchZone.R24ZoneRules(expected.ZoneEnabled,expected.ZoneDamage,expected.ZoneSpeed,expected.ZoneWait),map.CatalogMinX,map.CatalogMinZ,map.CatalogMaxX,map.CatalogMaxZ,0,random.Next);zone.Tick(loop.MatchClock,.1,true);Need(loop.MatchZoneOwner!=null&&loop.MatchZoneOwner.State!=null&&Math.Abs(loop.MatchZoneOwner.State.Next.X-zone.State.Next.X)<1e-7&&Math.Abs(loop.MatchZoneOwner.State.Next.Z-zone.State.Next.Z)<1e-7&&Math.Abs(loop.MatchZoneOwner.State.Ends-zone.State.Ends)<1e-7,"Actual zone owner uses shared seed and source plan epoch0");result.sharedZoneSeedApplied=true;
   loop.Rig.Head.Render();if(loop.MatchZone!=null)Need(loop.MatchZone.Visible,"Actual shared seeded zone submitted for rendering");var shaders=new HashSet<Shader>();foreach(var renderer in loop.Map.GetComponentsInChildren<Renderer>(true))foreach(var material in renderer.sharedMaterials)if(material!=null)shaders.Add(material.shader);foreach(string resource in new[]{"R24ZoneSurface","R24ZoneDanger"})shaders.Add(Resources.Load<Shader>(resource));foreach(var shader in shaders){Need(shader!=null,"Actual map/zone shader loaded");foreach(var message in ShaderUtil.GetShaderMessages(shader))Need(message.severity.ToString()!="Error",message.message);}
  }
